#!/usr/bin/env python3
"""Characterization tests for plan_to_pipeline_cli.py.

These tests capture the exact JSON output of plan_to_pipeline_cli.py
for a fixed set of representative inputs before the planner split.
"""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pytest

CLI = Path(__file__).resolve().parent / "plan_to_pipeline_cli.py"


def _run(plan: dict, question: str, route_prefix: str = "") -> dict:
    cmd = [sys.executable, str(CLI), "--plan-json", json.dumps(plan, separators=(",", ":")), "--question", question]
    if route_prefix:
        cmd += ["--route-prefix", route_prefix]
    result = subprocess.run(cmd, capture_output=True, text=True, cwd=str(CLI.parent.parent.parent))
    assert result.returncode == 0, result.stderr
    return json.loads(result.stdout)

